        let threshold = B748FuelConstants.FUEL_LOW_CTR_THRESHOLD_BEFORESTART;
        if (flightPhase >= FmsOperatingPhase.TAKEOFF) {
            threshold = B748FuelConstants.FUEL_LOW_CTR_THRESHOLD_CLIMB;
        }
        if (flightPhase >= FmsOperatingPhase.CRUISE) {
            threshold = B748FuelConstants.FUEL_LOW_CTR_THRESHOLD_CRUISE;
        }
        if (jett) {
            threshold = B748FuelConstants.FUEL_LOW_CTR_THRESHOLD_JETTISON;
        }
        const leftAlerting = (centerQty < threshold) && pumpLOn;
        const rightAlerting = (centerQty < threshold) && pumpROn;
        if ((leftAlerting || rightAlerting) && !ctrConfigAlerting && !this.fuelCtrConfigTimer.isPending()) {
            this.fuelCtrConfigTimer.schedule(() => this.fuelCtrConfigAlerting.set(true), 60000);
        }
        if (!(leftAlerting || rightAlerting)) {
            if (this.fuelCtrConfigTimer.isPending()) {
                this.fuelCtrConfigTimer.clear();
            }
            this.fuelCtrConfigAlerting.set(false);
        }
        this.leftCtrFuelLowAlerting.set(ctrConfigAlerting || jett ? false : leftAlerting);
        this.rightCtrFuelLowAlerting.set(ctrConfigAlerting || jett ? false : rightAlerting);
